"use strict";(globalThis.webpackChunkdoqumentation=globalThis.webpackChunkdoqumentation||[]).push([[1866],{8005(e,n,i){i.r(n),i.d(n,{assets:()=>u,contentTitle:()=>o,default:()=>p,frontMatter:()=>s,metadata:()=>t,toc:()=>d});const t=JSON.parse('{"id":"qiskit-addons/obp/getting_started","title":"Schaltkreistiefe reduzieren mit Operator-R\xfcckpropagation","description":"{/ doqumentation-source-hash: a68fadde /}","source":"@site/i18n/de/docusaurus-plugin-content-docs/current/qiskit-addons/obp/01_getting_started.mdx","sourceDirName":"qiskit-addons/obp","slug":"/qiskit-addons/obp/getting_started","permalink":"/qiskit-addons/obp/getting_started","draft":false,"unlisted":false,"editUrl":"https://github.com/JanLahmann/doQumentation/tree/main/docs/qiskit-addons/obp/01_getting_started.mdx","tags":[],"version":"current","sidebarPosition":1,"frontMatter":{"title":"Schaltkreistiefe reduzieren mit Operator-R\xfcckpropagation","sidebar_label":"Schaltkreistiefe reduzieren mit Operator-R\xfcckpropagation","notebook_path":"qiskit-addons/obp/01_getting_started.ipynb"},"sidebar":"qiskitAddonsSidebar","previous":{"title":"Verbesserung der Energiesch\xe4tzung eines fermionischen Gittermodells mit SQD","permalink":"/qiskit-addons/sqd/fermionic_lattice_hamiltonian"},"next":{"title":"Reduzierung des Trotter-Fehlers der Hamiltonischen Dynamik mit Multi-Produkt-Formeln","permalink":"/qiskit-addons/mpf/getting_started"}}');var r=i(74848),a=i(28453);const s={title:"Schaltkreistiefe reduzieren mit Operator-R\xfcckpropagation",sidebar_label:"Schaltkreistiefe reduzieren mit Operator-R\xfcckpropagation",notebook_path:"qiskit-addons/obp/01_getting_started.ipynb"},o=void 0,u={},d=[{value:"Schritt 1: Auf Quantenproblem abbilden",id:"step-1-map-to-quantum-problem",level:2},{value:"Die Zeitentwicklung eines Quanten-Heisenberg-Modells auf ein Quantenexperiment abbilden.",id:"map-the-time-evolution-of-a-quantum-heisenberg-model-to-a-quantum-experiment",level:3}];function c(e){const n={a:"a",code:"code",h2:"h2",h3:"h3",img:"img",li:"li",p:"p",pre:"pre",span:"span",strong:"strong",ul:"ul",...(0,a.R)(),...e.components},{OpenInLabBanner:t}=n;return t||function(e,n){throw new Error("Expected "+(n?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("OpenInLabBanner",!0),(0,r.jsxs)(r.Fragment,{children:["\n","\n",(0,r.jsx)(t,{notebookPath:"qiskit-addons/obp/01_getting_started.ipynb"}),"\n",(0,r.jsx)(n.p,{children:"Operator-R\xfcckpropagation ist eine Technik, bei der Operationen vom Ende eines Quantenschaltkreises in einen Pauli-Operator absorbiert werden, wodurch in der Regel die Tiefe des Schaltkreises auf Kosten zus\xe4tzlicher Terme im Operator verringert wird. Das Ziel ist es, so viel wie m\xf6glich vom Schaltkreis r\xfcckzupropagieren, ohne den Operator zu gro\xdf werden zu lassen."}),"\n",(0,r.jsxs)(n.p,{children:["Eine M\xf6glichkeit, eine tiefere R\xfcckpropagation in den Schaltkreis zu erm\xf6glichen und gleichzeitig zu verhindern, dass der Operator zu gro\xdf wird, besteht darin, Terme mit kleinen Koeffizienten abzuschneiden, anstatt sie zum Operator hinzuzuf\xfcgen. Das Abschneiden von Termen kann zu weniger auszuf\xfchrenden Quantenschaltkreisen f\xfchren, f\xfchrt jedoch zu einem gewissen Fehler bei der abschlie\xdfenden Erwartungswertberechnung, der proportional zur Gr\xf6\xdfe der Koeffizienten der abgeschnittenen Terme ist.\nIn diesem Tutorial implementierst du ein ",(0,r.jsx)(n.a,{href:"https://quantum.cloud.ibm.com/docs/guides/serverless#qiskit-patterns-with-quantum-serverless",children:"Qiskit-Muster"})," zur Simulation der Quantendynamik einer Heisenberg-Spinkette mittels Operator-R\xfcckpropagation:"]}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsxs)(n.li,{children:[(0,r.jsx)(n.strong,{children:"Schritt 1: Auf Quantenproblem abbilden"}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsx)(n.li,{children:"Den zeitentwickelten Hamiltonian auf einen Quantenschaltkreis abbilden"}),"\n"]}),"\n"]}),"\n",(0,r.jsxs)(n.li,{children:[(0,r.jsx)(n.strong,{children:"Schritt 2: Problem optimieren"}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsx)(n.li,{children:"Den Schaltkreis in Scheiben teilen"}),"\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsx)("font",{color:"#0F62FE",children:"Scheiben vom Schaltkreis auf ein Pauli-Observable r\xfcckpropagieren"}),"\n"]}),"\n",(0,r.jsx)(n.li,{children:"Die verbleibenden Scheiben zu einem einzelnen Schaltkreis zusammenf\xfchren"}),"\n",(0,r.jsx)(n.li,{children:"Den Schaltkreis f\xfcr das Backend transpilieren"}),"\n"]}),"\n"]}),"\n",(0,r.jsxs)(n.li,{children:[(0,r.jsx)(n.strong,{children:"Schritt 3: Experimente ausf\xfchren"}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsxs)(n.li,{children:["Den Erwartungswert mit dem reduzierten Schaltkreis und dem erweiterten Observable mithilfe eines ",(0,r.jsx)(n.a,{href:"https://quantum.cloud.ibm.com/docs/api/qiskit/qiskit.primitives.StatevectorEstimator",children:"StatevectorEstimator"})," berechnen \u2013 der Einfachheit halber in diesem Notebook"]}),"\n"]}),"\n"]}),"\n",(0,r.jsxs)(n.li,{children:[(0,r.jsx)(n.strong,{children:"Schritt 4: Ergebnisse rekonstruieren"}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsx)(n.li,{children:"Nicht zutreffend."}),"\n"]}),"\n"]}),"\n"]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"Hinweis:"})," Qiskit beschreibt ",(0,r.jsx)(n.a,{href:"https://quantum.cloud.ibm.com/docs/api/qiskit/qiskit.dagcircuit.DAGCircuit",children:"Schichten"})," im weiteren Sinne als Tiefe-1-Partitionen des Schaltkreises \xfcber alle Qubits. Dieses Paket verwendet den Begriff ",(0,r.jsx)(n.strong,{children:"Scheiben"}),", um Schichten mit beliebiger Tiefe zu beschreiben. Die Funktion ",(0,r.jsx)(n.a,{href:"https://qiskit.github.io/qiskit-addon-obp/stubs/qiskit_addon_obp.backpropagate.html",children:"qiskit_addon_obp.backpropagate"})," ist so gestaltet, dass sie jeweils ganze Scheiben r\xfcckpropagiert, sodass die Wahl, wie der Quantenschaltkreis aufgeteilt wird, einen gro\xdfen Einfluss darauf haben kann, wie gut die R\xfcckpropagation f\xfcr ein bestimmtes Problem funktioniert. Mehr \xfcber ",(0,r.jsx)(n.strong,{children:"Scheiben"})," erf\xe4hrst du weiter unten."]}),"\n",(0,r.jsx)(n.h2,{id:"step-1-map-to-quantum-problem",children:"Schritt 1: Auf Quantenproblem abbilden"}),"\n",(0,r.jsx)(n.h3,{id:"map-the-time-evolution-of-a-quantum-heisenberg-model-to-a-quantum-experiment",children:"Die Zeitentwicklung eines Quanten-Heisenberg-Modells auf ein Quantenexperiment abbilden."}),"\n",(0,r.jsxs)(n.p,{children:["Das Paket ",(0,r.jsx)(n.a,{href:"https://qiskit.github.io/qiskit-addon-utils/",children:"qiskit_addon_utils"})," stellt wiederverwendbare Funktionalit\xe4ten f\xfcr verschiedene Zwecke bereit."]}),"\n",(0,r.jsxs)(n.p,{children:["Sein Modul ",(0,r.jsx)(n.a,{href:"https://qiskit.github.io/qiskit-addon-utils/stubs/qiskit_addon_utils.problem_generators.html",children:"qiskit_addon_utils.problem_generators"})," enth\xe4lt Funktionen zum Erzeugen von Heisenberg-\xe4hnlichen Hamiltonians auf einem gegebenen Konnektivit\xe4tsgraphen.\nDieser Graph kann entweder ein ",(0,r.jsx)(n.a,{href:"https://www.rustworkx.org/apiref/rustworkx.PyGraph.html",children:"rustworkx.PyGraph"})," oder eine ",(0,r.jsx)(n.a,{href:"https://quantum.cloud.ibm.com/docs/api/qiskit/qiskit.transpiler.CouplingMap",children:"CouplingMap"})," sein, was die Verwendung in Qiskit-zentrierten Workflows erleichtert."]}),"\n",(0,r.jsxs)(n.p,{children:["Im Folgenden erzeugen wir zun\xe4chst eine Heavy-Hex-",(0,r.jsx)(n.code,{children:"CouplingMap"}),", aus der wir eine lineare Kette von 10 Qubits herausschneiden. Beachte, dass die Indizes dieser neuen ",(0,r.jsx)(n.code,{children:"reduced_coupling_map"})," wieder nullbasiert sind."]}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{className:"language-python",children:"# Added by doQumentation \u2014 required packages for this notebook\n!pip install -q numpy qiskit qiskit-addon-obp qiskit-addon-utils qiskit-ibm-runtime rustworkx\n"})}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{className:"language-python",children:"from qiskit.transpiler import CouplingMap\n\ncoupling_map = CouplingMap.from_heavy_hex(3, bidirectional=False)\n\n# Choose a 10-qubit linear chain on this coupling map\nreduced_coupling_map = coupling_map.reduce([0, 13, 1, 14, 10, 16, 5, 12, 8, 18])\n"})}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{className:"language-python",children:'from rustworkx.visualization import graphviz_draw\n\ngraphviz_draw(reduced_coupling_map.graph, method="circo")\n'})}),"\n",(0,r.jsx)(n.p,{children:(0,r.jsx)(n.img,{alt:"Code output",src:i(10039).A+"",width:"1595",height:"59"})}),"\n",(0,r.jsx)(n.p,{children:"Als N\xe4chstes erzeugen wir einen Pauli-Operator, der einen Heisenberg-XYZ-Hamiltonian modelliert."}),"\n",(0,r.jsx)(n.span,{className:"katex-error",title:"ParseError: KaTeX parse error: Can't use function '$' in math mode at position 158: \u2026} \\sigma_j^{z})$\u0332$\n\nDabei ist $G\u2026",style:{color:"#cc0000"},children:"    J_{y} \\sigma_j^{y} \\sigma_{k}^{y} + J_{z} \\sigma_j^{z} \\sigma_{k}^{z}) +\n    \\sum_{j\\in V} (h_{x} \\sigma_j^{x} + h_{y} \\sigma_j^{y} + h_{z} \\sigma_j^{z})$$\n\nDabei ist $G(V,E)$ der Graph der angegebenen CouplingMap.\n\n```python\nimport numpy as np\nfrom qiskit_addon_utils.problem_generators import generate_xyz_hamiltonian\n\n# Get a qubit operator describing the Heisenberg XYZ model\nhamiltonian = generate_xyz_hamiltonian(\n    reduced_coupling_map,\n    coupling_constants=(np.pi / 8, np.pi / 4, np.pi / 2),\n    ext_magnetic_field=(np.pi / 3, np.pi / 6, np.pi / 9),\n)\nprint(hamiltonian)\n```\n\n```text\nSparsePauliOp(['IIIIIIIXXI', 'IIIIIIIYYI', 'IIIIIIIZZI', 'IIIIIXXIII', 'IIIIIYYIII', 'IIIIIZZIII', 'IIIXXIIIII', 'IIIYYIIIII', 'IIIZZIIIII', 'IXXIIIIIII', 'IYYIIIIIII', 'IZZIIIIIII', 'IIIIIIIIXX', 'IIIIIIIIYY', 'IIIIIIIIZZ', 'IIIIIIXXII', 'IIIIIIYYII', 'IIIIIIZZII', 'IIIIXXIIII', 'IIIIYYIIII', 'IIIIZZIIII', 'IIXXIIIIII', 'IIYYIIIIII', 'IIZZIIIIII', 'XXIIIIIIII', 'YYIIIIIIII', 'ZZIIIIIIII', 'IIIIIIIIIX', 'IIIIIIIIIY', 'IIIIIIIIIZ', 'IIIIIIIIXI', 'IIIIIIIIYI', 'IIIIIIIIZI', 'IIIIIIIXII', 'IIIIIIIYII', 'IIIIIIIZII', 'IIIIIIXIII', 'IIIIIIYIII', 'IIIIIIZIII', 'IIIIIXIIII', 'IIIIIYIIII', 'IIIIIZIIII', 'IIIIXIIIII', 'IIIIYIIIII', 'IIIIZIIIII', 'IIIXIIIIII', 'IIIYIIIIII', 'IIIZIIIIII', 'IIXIIIIIII', 'IIYIIIIIII', 'IIZIIIIIII', 'IXIIIIIIII', 'IYIIIIIIII', 'IZIIIIIIII', 'XIIIIIIIII', 'YIIIIIIIII', 'ZIIIIIIIII'],\n              coeffs=[0.39269908+0.j, 0.78539816+0.j, 1.57079633+0.j, 0.39269908+0.j,\n 0.78539816+0.j, 1.57079633+0.j, 0.39269908+0.j, 0.78539816+0.j,\n 1.57079633+0.j, 0.39269908+0.j, 0.78539816+0.j, 1.57079633+0.j,\n 0.39269908+0.j, 0.78539816+0.j, 1.57079633+0.j, 0.39269908+0.j,\n 0.78539816+0.j, 1.57079633+0.j, 0.39269908+0.j, 0.78539816+0.j,\n 1.57079633+0.j, 0.39269908+0.j, 0.78539816+0.j, 1.57079633+0.j,\n 0.39269908+0.j, 0.78539816+0.j, 1.57079633+0.j, 1.04719755+0.j,\n 0.52359878+0.j, 0.34906585+0.j, 1.04719755+0.j, 0.52359878+0.j,\n 0.34906585+0.j, 1.04719755+0.j, 0.52359878+0.j, 0.34906585+0.j,\n 1.04719755+0.j, 0.52359878+0.j, 0.34906585+0.j, 1.04719755+0.j,\n 0.52359878+0.j, 0.34906585+0.j, 1.04719755+0.j, 0.52359878+0.j,\n 0.34906585+0.j, 1.04719755+0.j, 0.52359878+0.j, 0.34906585+0.j,\n 1.04719755+0.j, 0.52359878+0.j, 0.34906585+0.j, 1.04719755+0.j,\n 0.52359878+0.j, 0.34906585+0.j, 1.04719755+0.j, 0.52359878+0.j,\n 0.34906585+0.j])\n```\n\nAus dem Qubit-Operator k\xf6nnen wir einen Quantenschaltkreis erzeugen, der seine Zeitentwicklung modelliert.\nAuch hier hilft das Modul [qiskit_addon_utils.problem_generators](https://qiskit.github.io/qiskit-addon-utils/stubs/qiskit_addon_utils.problem_generators.html) mit einer praktischen Funktion genau daf\xfcr:\n\n```python\nfrom qiskit.synthesis import LieTrotter\nfrom qiskit_addon_utils.problem_generators import generate_time_evolution_circuit\n\ncircuit = generate_time_evolution_circuit(\n    hamiltonian,\n    time=0.2,\n    synthesis=LieTrotter(reps=2),\n)\ncircuit.draw(\"mpl\", style=\"iqp\", scale=0.6)\n```\n\n![Quantum circuit diagram](/img/qiskit-addons/obp/01-getting-started/output_2.png)\n\n## Schritt 2: Problem optimieren \\{#step-2-optimize-the-problem}\n### Schaltkreisscheiben f\xfcr die R\xfcckpropagation erstellen \\{#create-circuit-slices-to-backpropagate}\n\nDenke daran, dass die Funktion ``backpropagate`` jeweils ganze Schaltkreisscheiben r\xfcckpropagiert, sodass die Wahl der Aufteilung einen Einfluss darauf haben kann, wie gut die R\xfcckpropagation f\xfcr ein bestimmtes Problem funktioniert. Hier gruppieren wir Gates desselben Typs mithilfe der Funktion [slice_by_gate_types](https://qiskit.github.io/qiskit-addon-utils/stubs/qiskit_addon_utils.slicing.slice_by_gate_types.html) in Scheiben.\n\nEine ausf\xfchrlichere Diskussion \xfcber das Aufteilen von Schaltkreisen findest du in diesem [How-to-Leitfaden](https://qiskit.github.io/qiskit-addon-utils/how_tos/create_circuit_slices.html) des Pakets [qiskit-addon-utils](https://qiskit.github.io/qiskit-addon-utils/index.html).\n\n```python\nfrom qiskit_addon_utils.slicing import slice_by_gate_types\n\nslices = slice_by_gate_types(circuit)\nprint(f\"Separated the circuit into {len(slices)} slices.\")\n```\n\n```text\nSeparated the circuit into 18 slices.\n```\n\n### Einschr\xe4nken, wie gro\xdf der Operator w\xe4hrend der R\xfcckpropagation werden darf \\{#constrain-how-large-the-operator-may-grow-during-backpropagation}\n\nW\xe4hrend der R\xfcckpropagation n\xe4hert sich die Anzahl der Terme im Operator im Allgemeinen schnell $4^N$ an, wobei $N$ die Anzahl der Qubits ist. Die Gr\xf6\xdfe des Operators kann begrenzt werden, indem das Schl\xfcsselwortargument ``operator_budget`` der Funktion ``backpropagate`` angegeben wird, das eine [OperatorBudget](https://qiskit.github.io/qiskit-addon-obp/stubs/qiskit_addon_obp.utils.simplify.OperatorBudget.html)-Instanz akzeptiert.\n\nHier legen wir fest, dass die R\xfcckpropagation stoppen soll, wenn die Anzahl der qubit-weise kommutierenden Pauli-Gruppen im Operator 8 \xfcberschreitet.\n\n```python\nfrom qiskit_addon_obp.utils.simplify import OperatorBudget\n\nop_budget = OperatorBudget(max_qwc_groups=8)\n```\n\n### Scheiben vom Schaltkreis r\xfcckpropagieren \\{#backpropagate-slices-from-the-circuit}\n\nZun\xe4chst legen wir das Pauli-Z-Observable auf Qubit 0 fest und propagieren Scheiben aus dem Zeitentwicklungsschaltkreis zur\xfcck, bis die Terme im Observable nicht mehr zu 8 oder weniger qubit-weise kommutierenden Pauli-Gruppen zusammengefasst werden k\xf6nnen.\n\nIm Folgenden siehst du, dass wir 7 Scheiben r\xfcckpropagiert haben, aber nur 6 der 8 zugeteilten Pauli-Gruppen verwendet wurden. Das bedeutet, dass das R\xfcckpropagieren einer weiteren Scheibe dazu f\xfchren w\xfcrde, dass die Anzahl der Pauli-Gruppen 8 \xfcberschreitet. Wir k\xf6nnen \xfcberpr\xfcfen, ob das der Fall ist, indem wir die zur\xfcckgegebenen Metadaten untersuchen.\n\n```python\nfrom qiskit.quantum_info import SparsePauliOp\nfrom qiskit_addon_obp import backpropagate\nfrom qiskit_addon_utils.slicing import combine_slices\n\n# Specify a single-qubit observable\nobservable = SparsePauliOp(\"IIIIIIIIIZ\")\n\n# Backpropagate slices onto the observable\nbp_obs, remaining_slices, metadata = backpropagate(observable, slices, operator_budget=op_budget)\n# Recombine the slices remaining after backpropagation\nbp_circuit = combine_slices(remaining_slices, include_barriers=True)\n\nprint(f\"Backpropagated {metadata.num_backpropagated_slices} slices.\")\nprint(\n    f\"New observable has {len(bp_obs.paulis)} terms, which can be combined into {len(bp_obs.group_commuting(qubit_wise=True))} groups.\"\n)\nprint(\n    f\"Note that backpropagating one more slice would result in {metadata.backpropagation_history[-1].num_paulis[0]} terms \"\n    f\"across {metadata.backpropagation_history[-1].num_qwc_groups} groups.\"\n)\nprint(\"The remaining circuit after backpropagation looks as follows:\")\nbp_circuit.draw(\"mpl\", scale=0.6)\n```\n\n```text\nBackpropagated 7 slices.\nNew observable has 18 terms, which can be combined into 8 groups.\nNote that backpropagating one more slice would result in 27 terms across 12 groups.\nThe remaining circuit after backpropagation looks as follows:\n```\n\n![Quantum circuit diagram](/img/qiskit-addons/obp/01-getting-started/output_3.png)\n\nAls N\xe4chstes legen wir dasselbe Problem mit denselben Einschr\xe4nkungen f\xfcr die Gr\xf6\xdfe des Ausgabe-Observables fest. Diesmal weisen wir jedoch jeder Scheibe ein Fehlerbudget mithilfe der Funktion [setup_budet](https://qiskit.github.io/qiskit-addon-obp/stubs/qiskit_addon_obp.utils.truncating.setup_budget.html) zu. Pauli-Terme mit kleinen Koeffizienten werden aus jeder Scheibe abgeschnitten, bis das Fehlerbudget aufgebraucht ist, und das verbleibende Budget wird dem Budget der folgenden Scheibe hinzugef\xfcgt.\n\nUm dieses Abschneiden zu aktivieren, m\xfcssen wir unser Fehlerbudget wie folgt einrichten:\n\n```python\nfrom qiskit_addon_obp.utils.truncating import setup_budget\n\ntruncation_error_budget = setup_budget(max_error_per_slice=0.005)\n```\n\nBeachte, dass wir durch die Zuteilung von `5e-3` Fehler pro Scheibe f\xfcr das Abschneiden 3 weitere Scheiben aus dem Schaltkreis entfernen k\xf6nnen, w\xe4hrend wir innerhalb des urspr\xfcnglichen Budgets von 8 kommutierenden Pauli-Gruppen im Observable bleiben. Standardm\xe4\xdfig verwendet `backpropagate` die L1-Norm der abgeschnittenen Koeffizienten, um den durch das Abschneiden entstandenen Gesamtfehler zu begrenzen. Weitere Optionen findest du im [How-to-Leitfaden zur Angabe der p_norm](https://qiskit.github.io/qiskit-addon-obp/how_tos/bound_error_using_p_norm.html).\n\nIn diesem konkreten Beispiel, bei dem wir 10 Scheiben r\xfcckpropagiert haben, sollte der Gesamtabschneidefehler ``(5e-3 Fehler/Scheibe) * (10 Scheiben) = 5e-2`` nicht \xfcberschreiten.\nEine weiterf\xfchrende Diskussion zur Verteilung eines Fehlerbudgets \xfcber deine Scheiben findest du in [diesem How-to-Leitfaden](https://qiskit.github.io/qiskit-addon-obp/how_tos/truncate_operator_terms.html).\n\n```python\n# Run the same experiment but truncate observable terms with small coefficients\nbp_obs_trunc, remaining_slices_trunc, metadata = backpropagate(\n    observable, slices, operator_budget=op_budget, truncation_error_budget=truncation_error_budget\n)\n\n# Recombine the slices remaining after backpropagation\nbp_circuit_trunc = combine_slices(remaining_slices_trunc, include_barriers=True)\n\nprint(f\"Backpropagated {metadata.num_backpropagated_slices} slices.\")\nprint(\n    f\"New observable has {len(bp_obs_trunc.paulis)} terms, which can be combined into {len(bp_obs_trunc.group_commuting(qubit_wise=True))} groups.\\n\"\n    f\"After truncation, the error in our observable is bounded by {metadata.accumulated_error(0):.3e}\"\n)\nprint(\n    f\"Note that backpropagating one more slice would result in {metadata.backpropagation_history[-1].num_paulis[0]} terms \"\n    f\"across {metadata.backpropagation_history[-1].num_qwc_groups} groups.\"\n)\nprint(\"The remaining circuit after backpropagation looks as follows:\")\nbp_circuit_trunc.draw(\"mpl\", scale=0.6)\n```\n\n```text\nBackpropagated 10 slices.\nNew observable has 19 terms, which can be combined into 8 groups.\nAfter truncation, the error in our observable is bounded by 4.933e-02\nNote that backpropagating one more slice would result in 27 terms across 13 groups.\nThe remaining circuit after backpropagation looks as follows:\n```\n\n![Quantum circuit diagram](/img/qiskit-addons/obp/01-getting-started/output_4.png)\n\n### Jetzt, da wir unsere reduzierten Ans\xe4tze und erweiterten Observables haben, k\xf6nnen wir unsere Experimente f\xfcr das Backend transpilieren. \\{#now-that-we-have-our-reduced-ansatze-and-expanded-observables-we-can-transpile-our-experiments-to-the-backend}\n\nHier verwenden wir das 14-Qubit-[FakeMelbourneV2](https://quantum.cloud.ibm.com/docs/api/qiskit-ibm-runtime/fake-provider-fake-melbourne-v2) aus [qiskit-ibm-runtime](https://quantum.cloud.ibm.com/docs/api/qiskit-ibm-runtime), um zu zeigen, wie man f\xfcr ein QPU-Backend transpiliert.\n\n```python\nfrom qiskit.transpiler.preset_passmanagers import generate_preset_pass_manager\nfrom qiskit_ibm_runtime.fake_provider import FakeMelbourneV2\n\n# Specify a backend and a pass manager for transpilation\nbackend = FakeMelbourneV2()\npm = generate_preset_pass_manager(backend=backend, optimization_level=1)\n\n# Transpile original experiment\ncircuit_isa = pm.run(circuit)\nobservable_isa = observable.apply_layout(circuit_isa.layout)\n\n# Transpile backpropagated experiment\nbp_circuit_isa = pm.run(bp_circuit)\nbp_obs_isa = bp_obs.apply_layout(bp_circuit_isa.layout)\n\n# Transpile the backpropagated experiment with truncated observable terms\nbp_circuit_trunc_isa = pm.run(bp_circuit_trunc)\nbp_obs_trunc_isa = bp_obs_trunc.apply_layout(bp_circuit_trunc_isa.layout)\n```\n\n## Schritt 3: Quantenexperimente ausf\xfchren \\{#step-3-execute-quantum-experiments}\n### Erwartungswert berechnen \\{#calculate-expectation-value}\n\nSchlie\xdflich k\xf6nnen wir die r\xfcckpropagieren Experimente ausf\xfchren und sie mit dem vollst\xe4ndigen Experiment unter Verwendung des rauschfreien [StatevectorEstimator](https://quantum.cloud.ibm.com/docs/api/qiskit/qiskit.primitives.StatevectorEstimator) vergleichen. Wir k\xf6nnen sehen, dass der r\xfcckpropagierte Erwartungswert ohne Abschneiden innerhalb der Grenzen der numerischen Genauigkeit \xe4quivalent zum exakten Wert ist.\n\nDer Erwartungswert des Operators mit abgeschnittenen Termen weist einen Fehler in der Gr\xf6\xdfenordnung von ``1e-4`` auf, was innerhalb der erwarteten Toleranz liegt.\n\n**Hinweis:** Wir verwenden einen zustandsvektorbasierten ``Estimator``-Primitiven, um den Effekt des Abschneidens auf die Ausgabe zu veranschaulichen. Um auf dem Backend auszuf\xfchren, f\xfcr das die Experimente in Schritt 2 transpiliert wurden, w\xfcrde man den [EstimatorV2](https://quantum.cloud.ibm.com/docs/api/qiskit-ibm-runtime/estimator-v2) aus ``qiskit-ibm-runtime`` importieren und die Backend-Instanz an den Konstruktor \xfcbergeben.\n\n```python\nfrom qiskit.primitives import StatevectorEstimator as Estimator\n\nestimator = Estimator()\n\n# Run the experiments using Estimator primitive\nresult_exact = estimator.run([(circuit_isa, observable_isa)]).result()[0].data.evs.item()\nresult_bp = estimator.run([(bp_circuit_isa, bp_obs_isa)]).result()[0].data.evs.item()\nresult_bp_trunc = (\n    estimator.run([(bp_circuit_trunc_isa, bp_obs_trunc_isa)]).result()[0].data.evs.item()\n)\n\nprint(f\"Exact expectation value: {result_exact}\")\nprint(f\"Backpropagated expectation value: {result_bp}\")\nprint(f\"Backpropagated expectation value with truncation: {result_bp_trunc}\")\nprint(f\"    - Expected Error for truncated observable: {metadata.accumulated_error(0):.3e}\")\nprint(f\"    - Observed Error for truncated observable: {abs(result_exact - result_bp_trunc):.3e}\")\n```\n\n```text\nExact expectation value: 0.8854160687717507\nBackpropagated expectation value: 0.8854160687717532\nBackpropagated expectation value with truncation: 0.8850236647156059\n    - Expected Error for truncated observable: 4.933e-02\n    - Observed Error for truncated observable: 3.924e-04\n```\n\n<TutorialFeedback />"})]})}function p(e={}){const{wrapper:n}={...(0,a.R)(),...e.components};return n?(0,r.jsx)(n,{...e,children:(0,r.jsx)(c,{...e})}):c(e)}},10039(e,n,i){i.d(n,{A:()=>t});const t="data:image/png;base64,"},28453(e,n,i){i.d(n,{R:()=>s,x:()=>o});var t=i(96540);const r={},a=t.createContext(r);function s(e){const n=t.useContext(a);return t.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function o(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(r):e.components||r:s(e.components),t.createElement(a.Provider,{value:n},e.children)}}}]);